<?php
namespace App\Jobs; use App\Models\FiscalCatalogVersion; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\{DB,Http,Storage}; use Illuminate\Support\Str; use Throwable;
class ImportCatalogSpreadsheet implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $timeout=3600;public function __construct(public string $versionId){}public function handle():void{$v=FiscalCatalogVersion::findOrFail($this->versionId);$stream=Storage::disk(config('filesystems.default'))->readStream($v->storage_path);try{$response=Http::timeout(3600)->withToken(config('services.fiscal_engine.token'))->attach('file',$stream,$v->source_filename)->post(config('services.fiscal_engine.url').'/v1/catalogs/normalize',['catalog_version_id'=>$v->id,'valid_from'=>(string)$v->valid_from,'base_version_id'=>$v->manifest['base_version_id']??FiscalCatalogVersion::published()->whereKeyNot($v->id)->latest('published_at')->value('id')]);$response->throw();$data=$response->json();DB::transaction(function()use($v,$data){$baseId=$v->manifest['base_version_id']??FiscalCatalogVersion::published()->whereKeyNot($v->id)->value('id');if($baseId){DB::statement('INSERT INTO cst_catalog_entries (catalog_version_id,cst,description,applicable_nfe,indicators,source_sheet,source_row,created_at,updated_at) SELECT ?,cst,description,applicable_nfe,indicators,source_sheet,source_row,now(),now() FROM cst_catalog_entries WHERE catalog_version_id=?',[$v->id,$baseId]);DB::statement('INSERT INTO cclass_catalog_entries (catalog_version_id,cclass_trib,cst,name,description,legal_basis,law_text,rate_type,ibs_reduction_percent,cbs_reduction_percent,valid_from,valid_to,updated_at_source,applicable_nfe,source_url,indicators,format_warning,source_sheet,source_row,created_at,updated_at) SELECT ?,cclass_trib,cst,name,description,legal_basis,law_text,rate_type,ibs_reduction_percent,cbs_reduction_percent,valid_from,valid_to,updated_at_source,applicable_nfe,source_url,indicators,format_warning,source_sheet,source_row,now(),now() FROM cclass_catalog_entries WHERE catalog_version_id=?',[$v->id,$baseId]);}
 foreach(array_chunk($data['entries'],500) as $chunk){DB::table('ncm_class_trib_entries')->insert(array_map(fn($r)=>array_merge($r,['id'=>(string)Str::uuid(),'catalog_version_id'=>$v->id,'conditions'=>json_encode($r['conditions']??[]),'validation_issues'=>json_encode($r['validation_issues']??[]),'created_at'=>now(),'updated_at'=>now()]),$chunk));}
 foreach(array_chunk($data['issues'],500) as $chunk)DB::table('catalog_import_issues')->insert(array_map(fn($r)=>array_merge($r,['catalog_version_id'=>$v->id,'context'=>json_encode($r['context']??[]),'created_at'=>now(),'updated_at'=>now()]),$chunk));$v->update(['status'=>collect($data['issues'])->contains(fn($i)=>$i['severity']==='error')?'draft':'validated','manifest'=>array_merge($v->manifest??[],$data['manifest']??[])]);});}catch(Throwable $e){$v->update(['status'=>'rejected','manifest'=>array_merge($v->manifest??[],['error'=>$e->getMessage()])]);throw $e;}finally{if(is_resource($stream))fclose($stream);}}}
